@dataclass(frozen=True, slots=True)
class LlmConfig:
    """Configuration for an LLM provider/model via liter-llm."""

    model: str = ""

    """Provider/model string using liter-llm routing format."""

    api_key: str | None = None

    """API key for the provider. When `None`, liter-llm falls back to the provider's standard environment variable (e.g., `OPENAI_API_KEY`)."""

    base_url: str | None = None

    """Custom base URL override for the provider endpoint."""

    timeout_secs: int | None = None

    """Request timeout in seconds. When `None`, liter-llm's built-in 60s default applies, except the VLM OCR path which uses a 300s default (a single page image transcription routinely exceeds 60s). Set explicitly to override."""

    max_retries: int | None = None

    """Maximum retry attempts (default: 3)."""

    temperature: float | None = None

    """Sampling temperature for generation tasks."""

    max_tokens: int | None = None

    """Maximum tokens to generate."""

    top_p: float | None = None

    """Nucleus sampling parameter for generation tasks, applied to individual requests built from this config. Restricts sampling to the smallest set of tokens whose cumulative probability mass is at least this value; lower is more focused. Validated to `[0.0, 1.0]` by [`LlmConfig::validate`]."""

    stop: list[str] | None = None

    """Stop sequence(s) that halt token generation, applied to individual requests built from this config."""

    seed: int | None = None

    """Random seed for reproducible outputs, applied to individual requests built from this config. Provider support varies -- some silently ignore it."""

    presence_penalty: float | None = None

    """Presence penalty for generation tasks, applied to individual requests built from this config. Positive values discourage the model from repeating topics already present in the conversation. Validated to `[-2.0, 2.0]` by [`LlmConfig::validate`]."""

    frequency_penalty: float | None = None

    """Frequency penalty for generation tasks, applied to individual requests built from this config. Positive values discourage the model from repeating the same tokens verbatim. Validated to `[-2.0, 2.0]` by [`LlmConfig::validate`]."""

    reasoning_effort: str | None = None

    """Reasoning effort level for extended-thinking models, applied to individual requests built from this config."""

    extra_body: str | None = None

    """Provider-specific extra parameters merged into the request body (guardrails, safety settings, grounding config, etc.), applied to individual requests built from this config."""

    load_env: bool | None = None

    """Whether liter-llm should load provider credentials from environment variables."""

    headers: dict[str, str] | None = None

    """Extra HTTP headers sent with every request to the provider."""

    providers: list[LlmProviderConfig] | None = None

    """Custom provider configurations, in addition to liter-llm's built-in providers."""

    cache: LlmCacheConfig | None = None

    """Response cache configuration."""

    budget: LlmBudgetConfig | None = None

    """Budget enforcement configuration."""

    rate_limit: LlmRateLimitConfig | None = None

    """Per-model rate limiting configuration."""

    cost_tracking: bool | None = None

    """Enable per-request cost tracking."""

    tracing: bool | None = None

    """Enable OpenTelemetry-compatible tracing spans."""

    cooldown_secs: int | None = None

    """Cooldown duration after transient errors, in seconds."""

    health_check_secs: int | None = None

    """Background health check interval, in seconds."""

    bedrock: BedrockConfig | None = None

    """AWS Bedrock settings (region, cross-region routing, explicit credentials)."""

    credential_provider: CredentialProviderConfig | None = None

    """Managed OAuth2/STS credential provider for auth modes liter-llm cannot express via a static `api_key` -- Azure AD, Vertex AI OAuth2, Vertex AI Application Default Credentials, and AWS STS Web Identity (EKS IRSA) for Bedrock."""

    max_concurrency: int | None = None

    """Maximum number of simultaneously in-flight requests to the LLM provider this config resolves to."""

    max_response_bytes: int | None = None

    """Maximum size, in bytes, of a single HTTP response body read from the LLM provider."""

    @staticmethod
    def from_json(json_str: str) -> LlmConfig:
        """Build a LlmConfig from a JSON string, via the native binding."""
        return _from_native_llm_config(_xberg.LlmConfig.from_json(json_str))


