    discard_suspected_ocr_noise: bool = False

    """Discard non-empty OCR text when any configured recognition-noise signal fires."""

    min_avg_word_length: float = 2

    """Minimum average word length. Below this with enough words indicates garbled extraction."""

    min_words_for_avg_length_check: int = 50

    """Minimum word count before average word length check applies."""

    min_consecutive_repeat_ratio: float = 0.08

    """Minimum consecutive word repetition ratio to detect column scrambling."""

    min_words_for_repeat_check: int = 50

    """Minimum word count before consecutive repetition check is applied."""

    substantive_min_chars: int = 100

    """Minimum character count for "substantive markdown" OCR skip gate."""

    non_text_min_chars: int = 20

    """Minimum character count for "non-text content" OCR skip gate."""

    alnum_ws_ratio_threshold: float = 0.4

    """Alphanumeric+whitespace ratio threshold for skip decisions."""

    pipeline_min_quality: float = 0.5

    """Minimum quality score (0.0-1.0) for a pipeline stage result to be accepted. If the result from a backend scores below this, try the next backend."""

    min_undecodable_ratio: float = 0.5

    """Minimum fraction of non-whitespace characters that are undecodable (Unicode Private Use Area, replacement characters, or non-whitespace control characters) before a page's text layer is treated as unreadable and routed to OCR (issue #1254). Gated by `min_total_non_whitespace` so short snippets with a stray symbol or two do not trip this check."""

    enable_provenance_ocr_routing: bool = True

    """Whether to route a page to OCR when xberg_native_pdf reports that a high fraction of its text was fabricated rather than read from the file (`MappingProvenance::Fallback`, xberg_native_pdf 0.3.75+, issue #1254). This is a direct fact from the extractor's ISO 32000-1 §9.10.2 mapping cascade, distinct from the character-heuristic proxy behind `min_undecodable_ratio`. Defaults to `true`."""

    min_provenance_fallback_ratio: float = 0.5

    """Minimum fraction of a page's non-whitespace characters with `MappingProvenance::Fallback` provenance before the page is treated as having a fabricated text layer and routed to OCR (issue #1254). Gated by `min_total_non_whitespace` so a short page with a stray fallback character cannot trip it. Only used when `enable_provenance_ocr_routing` is `true`."""

    enable_plausibility_ocr_routing: bool = True

